ALTER TABLE orders ALTER COLUMN public_id SET DEFAULT gen_random_uuid();

CREATE PROCEDURE backfill_public_id(batch_size int DEFAULT 10000)
LANGUAGE plpgsql
AS $$
DECLARE
  max_id bigint;
  start_id bigint := 1;
BEGIN
  SELECT max(id) INTO max_id FROM orders;
  RAISE NOTICE 'Backfilling public_id for ids up to %', max_id;
  WHILE start_id <= max_id LOOP
    UPDATE orders SET public_id = gen_random_uuid()
    WHERE id BETWEEN start_id AND start_id + batch_size - 1
      AND public_id IS NULL;
    COMMIT;
    start_id := start_id + batch_size;
  END LOOP;
END;
$$;

CALL backfill_public_id(10000);

ALTER TABLE orders ALTER COLUMN public_id SET NOT NULL;

DROP PROCEDURE backfill_public_id(int);
